:root {
  --bg-card: #1a1033;
  --bg-header: #2a1a55;
  --bg-headliner: #3d2270;
  --bg-item: #241540;
  --bg-tab-active: #f0c040;
  --bg-tab: #2a1a55;
  --color-accent: #f0c040;
  --color-accent-alt: #e0607a;
  --color-text-primary: #f0eaff;
  --color-text-secondary: #a890cc;
  --color-text-muted: #7a60a0;
  --color-label: #c0a8ff;
  --color-tab-active: #1a1033;
  --color-tab: #a890cc;
  --color-tag-alt-bg: #4a2040;
  --color-tag-alt-text: #e0607a;
  --color-tag-plain-bg: #2a2045;
  --color-tag-plain-text: #7a60a0;
  --color-border: #3a2560;
  --color-footer-bg: #120c28;
  --radius-card: 16px;
  --radius-tab: 20px;
  --radius-tag: 6px;
  --radius-badge: 10px;
}

.festival-card {
  width: 500px;
  background: var(--bg-card);
  border-radius: var(--radius-card);
  overflow: hidden;
  margin: 0 auto;
  border: 1px solid var(--color-border);
}

.festival-header {
  background: var(--bg-header);
  padding: 16px 20px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 1px solid var(--color-border);
}

.festival-title-block {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.festival-label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 2px;
  color: var(--color-label);
}

.festival-name {
  font-size: 22px;
  font-weight: 800;
  color: var(--color-accent);
  margin: 0;
  line-height: 1.1;
}

.festival-date {
  font-size: 12px;
  color: var(--color-text-secondary);
  margin: 0;
}

.festival-badge {
  background: var(--color-accent);
  border-radius: var(--radius-badge);
  width: 52px;
  height: 52px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0px;
}

.badge-day {
  font-size: 10px;
  font-weight: 700;
  color: var(--color-tab-active);
  letter-spacing: 1px;
  line-height: 1;
}

.badge-num {
  font-size: 24px;
  font-weight: 800;
  color: var(--color-tab-active);
  line-height: 1.1;
}

.stage-tabs {
  display: flex;
  gap: 8px;
  padding: 12px 20px;
  background: var(--bg-card);
  border-bottom: 1px solid var(--color-border);
}

.tab {
  padding: 5px 14px;
  border-radius: var(--radius-tab);
  font-size: 12px;
  font-weight: 600;
  color: var(--color-tab);
  background: var(--bg-tab);
  cursor: pointer;
}

.tab-active {
  background: var(--bg-tab-active);
  color: var(--color-tab-active);
}

.lineup-list {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 8px 12px;
}

.lineup-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 12px;
  background: var(--bg-item);
  border-radius: 10px;
}

.headliner {
  background: var(--bg-headliner);
  border: 1px solid var(--color-accent);
}

.item-time {
  font-size: 12px;
  font-weight: 600;
  color: var(--color-text-muted);
  width: 52px;
  flex-shrink: 0;
}

.item-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
  flex: 1;
}

.item-name {
  font-size: 14px;
  font-weight: 700;
  color: var(--color-text-primary);
}

.item-genre {
  font-size: 11px;
  color: var(--color-text-secondary);
}

.item-tag {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1px;
  padding: 3px 8px;
  border-radius: var(--radius-tag);
  background: var(--color-accent);
  color: var(--color-tab-active);
}

.tag-alt {
  background: var(--color-tag-alt-bg);
  color: var(--color-tag-alt-text);
}

.tag-plain {
  background: var(--color-tag-plain-bg);
  color: var(--color-tag-plain-text);
}

.festival-footer {
  display: flex;
  justify-content: space-between;
  padding: 10px 20px;
  background: var(--color-footer-bg);
  border-top: 1px solid var(--color-border);
}

.footer-info {
  font-size: 12px;
  color: var(--color-text-secondary);
}
